set DEFINES {}
if {[info exists ::env(GENUS_DEFINES)] && [string trim $::env(GENUS_DEFINES)] ne ""} {
    set DEFINES [split $::env(GENUS_DEFINES)]
    puts "DEFINES  = $DEFINES"
}

if {[llength $DEFINES] > 0} {
    # Genus supports passing SV defines via -define {A B C} on read_hdl.
    read_hdl -sv -define $DEFINES -f $FILELIST
} else {
    read_hdl -sv -f $FILELIST
}

elaborate $TOP
check_design -unresolved > $OUTDIR/reports/check_unresolved_pre_sdc.rpt

if {[file exists $SDC]} {
    read_sdc $SDC
} else {
